mapper.select:
select id, product_id, available, frozen, create_time, update_time
from tcc_inventory
where product_id = #{productId}

mapper.update:
update tcc_inventory
set available = available - #{quantity},
    frozen    = frozen + #{quantity}
where product_id = #{productId}
  and available >= #{quantity}

update tcc_inventory
set frozen = frozen - #{quantity}
where product_id = #{productId}
  and frozen >= #{quantity}

update tcc_inventory
set available = available + #{quantity},
    frozen    = frozen - #{quantity}
where product_id = #{productId}
  and frozen >= #{quantity}

mapper.select:
select id, user_id, balance, frozen, create_time, update_time
from tcc_account
where user_id = #{userId}

mapper.update:
update tcc_account
set balance = balance - #{amount},
    frozen  = frozen + #{amount}
where user_id = #{userId}
  and balance >= #{amount}

update tcc_account
set frozen = frozen - #{amount}
where user_id = #{userId}
  and frozen >= #{amount}

update tcc_account
set balance = balance + #{amount},
    frozen  = frozen - #{amount}
where user_id = #{userId}
  and frozen >= #{amount}

mapper.select:
select id, order_no, xid, user_id, product_id, quantity, amount, status, create_time, update_time
from tcc_order
where xid = #{xid}

mapper.update:
update tcc_order
set status = #{status}
where xid = #{xid}
